  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_gap_km double precision;
  v_center_km double precision;
  v_invalid integer;
begin
  select h.id,h.distance_km,h.latitude,h.longitude,t.status into v_route
  from public.hiking_routes h
  join public.hiking_route_tracks t on t.route_id=h.id
  where h.id='osm-relation-12700638'
    and h.source='openstreetmap'
    and h.name='Camino Natural del Románico Palentino. Ruta del Carbón de cok. Etapa 1'
    and h.route_type='Lineal'
    and h.official_url='https://www.mapa.gob.es/es/desarrollo-rural/temas/caminos-naturales/caminos-naturales/sector-noroeste/romanico-palentino/etapai/default.aspx'
    and exists (select 1 from public.hiking_route_regions g where g.route_id=h.id and g.published);
  if not found then raise exception 'Románico Palentino stage 1 route changed'; end if;
  if v_route.status='ready' then return; end if;
  with p as (
    select ordinality n,(point->>0)::float8 lat,(point->>1)::float8 lon
    from jsonb_array_elements(v_coords) with ordinality x(point,ordinality)
  ),s as (
    select *,lag(lat) over(order by n) pl,lag(lon) over(order by n) po from p
  ),d as (
    select case when pl is null then 0 else
      ST_DistanceSphere(ST_MakePoint(po,pl),ST_MakePoint(lon,lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(v_route.longitude,v_route.latitude),
        ST_MakePoint(lon,lat))/1000 center_km,
      lat between 27 and 45 and lon between -19 and 5 valid
    from s
  )
  select count(*),sum(step_km),max(step_km),min(center_km),
    count(*) filter(where not valid)
    into v_count,v_length_km,v_gap_km,v_center_km,v_invalid from d;
  if v_count<>1589 or v_invalid>0 or v_gap_km>0.15 or v_center_km>2.0
     or abs(v_length_km/17.0-1)>0.05
     or abs(v_length_km/v_route.distance_km-1)>0.05 then
    raise exception 'Románico Palentino GPX mismatch: points %, length %, step %, center %, invalid %',
      v_count,v_length_km,v_gap_km,v_center_km,v_invalid;
  end if;
  select jsonb_agg(jsonb_build_object('lat',(point->>0)::float8,
    'lon',(point->>1)::float8) order by ordinality)
    into v_points from jsonb_array_elements(v_coords) with ordinality x(point,ordinality);
  insert into public.hiking_route_tracks
    (route_id,status,segments,checked_at,continuity_checked,
      geometry_source,geometry_source_url,official)
  values ('osm-relation-12700638','ready',jsonb_build_array(v_points),now(),true,
    'Ministerio de Agricultura, Pesca y Alimentación - Caminos Naturales',
    'https://caminosnaturales.es/dam/caminos-naturales/caminos-naturales/Sector_I_Noroeste/romanico-palentino/etapai/tracks/012701rutacok_romanicopalentinogpx_540426.zip',true)
  on conflict(route_id) do update set
    status=excluded.status,segments=excluded.segments,
    checked_at=excluded.checked_at,continuity_checked=true,
    geometry_source=excluded.geometry_source,
    geometry_source_url=excluded.geometry_source_url,official=true;
  update public.hiking_routes
    set trace_available=true,published=true,
      official_url='https://caminosnaturales.es/es/red-de-caminos-naturales/camino-detalle/sector-noroeste/romanico-palentino/etapa1'
    where id='osm-relation-12700638';
end
